#include <iostream>
#include <string>
#include <stdexcept>
using namespace std;

int main() {
    try {
        int n = stoi("{word}");
        cout << n << endl;
    } catch (const invalid_argument& e) {
        cout << "接住了：" << e.what() << endl;
    }
    return 0;
}
